"""Present aligned renderer/reference captures without modifying their pixels."""
import argparse, html, json, shutil
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--input',type=Path,default=Path('/tmp/dreamland-reference-final'));p.add_argument('--out',type=Path,default=Path('/tmp/dreamland-reference-review'));p.add_argument('--reference',type=Path,default=Path('/home/claude/.artifacts/dreamland-reference-match/reference.png'));p.add_argument('--play-url',default='');a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True)
shutil.copy(a.reference,a.out/'reference.png')
shutil.copy(Path(__file__).with_name('reference-layout.json'),a.out/'reference-layout.json')
for f in a.input.iterdir():
 if f.is_file() and f.suffix in ('.png','.json'):shutil.copy(f,a.out/f.name)
assert (a.out/'restored.png').exists(), 'Reference-position renderer capture required'
views=''
for name,label in [('unrestored.png','Collapsed / unrestored'),('rotated45.png','3D view at 45°'),('rotated90.png','3D view at 90°')]:
 if (a.out/name).exists():views+=f'<figure><img src="{name}" alt="{label}"><figcaption>{label}</figcaption></figure>'
play=f'<p><a href="{html.escape(a.play_url,quote=True)}">Open the fake map — Q/E rotates the view</a></p>' if a.play_url else ''
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dreamland reference match</title><style>*{box-sizing:border-box}body{background:#18201b;color:#e6ecd9;font:16px/1.5 system-ui;margin:0}main{max-width:1400px;padding:24px;margin:auto}a{color:#c5e592}h1{line-height:1.15}p{max-width:950px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,450px),1fr));gap:20px}figure{margin:0}img{display:block;width:100%;image-rendering:pixelated}figcaption{padding:8px 0}.overlay{position:relative;max-width:960px}.overlay img+img{position:absolute;inset:0;height:100%;opacity:.5}label{display:block;margin:16px 0}input{max-width:100%;width:360px;vertical-align:middle}section{margin-top:32px}</style><main><h1>Dreamland reference match in the game renderer</h1><p>A dedicated fake map follows the supplied reference’s ground and object layout. Houses use the game’s 3D renderer. Fences and benches are omitted as requested. The scene is a reference study, separate from real-world map generation.</p>PLAY<div class="grid"><figure><img src="reference.png" alt="Supplied reference frame"><figcaption>Reference</figcaption></figure><figure><img src="restored.png" alt="Restored scene in the game renderer"><figcaption>Actual renderer, reference heading</figcaption></figure></div><section><h2>Check alignment</h2><p>Blend the captures to inspect object positions, silhouettes and ground boundaries. The reference’s omitted benches and fences remain visible in its layer.</p><label>Renderer opacity <input id="blend" type="range" min="0" max="100" value="50"> <output id="value">50%</output></label><div class="overlay"><img src="reference.png" alt="Reference alignment layer"><img id="render" src="restored.png" alt="Renderer alignment layer"></div></section><section><h2>State and rotation checks</h2><div class="grid">VIEWS</div><p><a href="audit.json">Renderer and object coverage audit</a> · <a href="reference-layout.json">Object positions and native source crops</a></p><p>The supplied GIF includes moving light and character animation. These stills compare a single moment; hidden walls and roof backs are reconstructed as 3D surfaces.</p></section></main><script>const b=document.getElementById('blend');b.addEventListener('input',()=>{document.getElementById('render').style.opacity=b.value/100;document.getElementById('value').value=b.value+'%'});</script></html>'''
(a.out/'index.html').write_text(page.replace('PLAY',play).replace('VIEWS',views))
print(a.out)
